export function translate(text: string, locale: Locale): string {
  if (locale === "en") return text;
  const key = text.trim();
  if (!key) return text;
  const leading = text.match(/^\s*/)?.[0] ?? "";
  const trailing = text.match(/\s*$/)?.[0] ?? "";
  const localize = (value: string) => `${leading}${value}${trailing}`;
  const exact = sw[key] ?? swContent[key];
  if (exact) return localize(exact);

  let match = key.match(/^(\d+) sale(s?)$/i);
  if (match) return localize(`${match[1]} mauzo`);
  match = key.match(/^(\d+) sold$/i);
  if (match) return localize(`${match[1]} zimeuzwa`);
  match = key.match(/^(\d+) in stock$/i);
  if (match) return localize(`${match[1]} zipo stoku`);
  match = key.match(/^(\d+) left \(alert at (\d+)\)$/i);
  if (match) return localize(`Zimebaki ${match[1]} (tahadhari kwa ${match[2]})`);
  match = key.match(/^Sale recorded — total TZS (.+)$/);
  if (match) return localize(`Mauzo yamerekodiwa — jumla ya TZS ${match[1]}`);
  match = key.match(/^Restock recorded — total TZS (.+)$/);
  if (match) return localize(`Stoku imejazwa — jumla ya TZS ${match[1]}`);
  match = key.match(/^Record sale — TZS (.+)$/);
  if (match) return localize(`Rekodi mauzo — TZS ${match[1]}`);
  match = key.match(/^Record restock — TZS (.+)$/);
  if (match) return localize(`Rekodi ujazaji wa stoku — TZS ${match[1]}`);
  match = key.match(/^(\d+(?:\.\d+)?) units?$/i);
  if (match) return localize(`${match[1]} vipimo`);
  match = key.match(/^Current cost (.+) · (\d+) in stock$/);
  if (match) return localize(`Gharama ya sasa ${match[1]} · ${match[2]} zipo stoku`);

  return text;
}
